import type { IconComponent } from '@wix/wix-ui-icons-common/core';
import { Settings } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext, useEffect, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { useModalService } from './../../ricos-modals/index.js';
import type { IToolbarItem, ToolbarButton } from './../../ricos-types/index.js';
import type { ToolbarButtonCommand } from './../../ricos-types/plugin-types.js';

import { PLUGIN_TOOLBAR_SETTINGS_BUTTON } from '../data-hooks.js';
import { getNodeInSelection } from '../resolvers/get-node-in-selection.js';
import { ToolbarButton as ToolbarButtonComponent } from '../toolbar-button/toolbar-button.js';
import { PLUGIN_TOOLBAR_BUTTON_ID } from './plugin-toolbar-buttons-ids.js';

export const createSettingsButton = ({
  modalId,
  command,
  attributes,
  showLabel,
  dataHook,
  buttonId,
  icon: Icon = Settings,
  tooltip = 'SettingsButton_Tooltip',
}: {
  modalId: string;
  command: ToolbarButtonCommand;
  attributes?: ToolbarButton['attributes'];
  showLabel?: boolean;
  dataHook?: string;
  buttonId?: string;
  icon?: IconComponent;
  tooltip?: string;
}): ToolbarButton => {
  return {
    id: buttonId ?? PLUGIN_TOOLBAR_BUTTON_ID.SETTINGS,
    type: 'modal',
    attributes: {
      selectedNode: getNodeInSelection,
      active: (_, { modals }) => Boolean(modals?.getModal(modalId)),
      ...attributes,
    },
    icon: Icon,
    tooltip,
    dataHook: dataHook ?? PLUGIN_TOOLBAR_SETTINGS_BUTTON,
    renderer: toolbarItem => <SettingsButton toolbarItem={toolbarItem} showLabel={showLabel} />,
    command,
  };
};

const SettingsButton: React.FC<{
  toolbarItem: IToolbarItem;
  dataHook?: string;
  showLabel?: boolean;
}> = ({ toolbarItem, dataHook, showLabel }) => {
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const [isActive, setIsActive] = useState(toolbarItem.attributes.active);
  const { isMobile, t } = useContext(RicosContext) || {};
  const modalService = useModalService();
  const onClick = toolbarItem.commands.click;
  const Icon = toolbarItem.presentation.icon;
  const tooltip = t(toolbarItem.presentation.tooltip);

  useEffect(() => {
    modalService.onModalOpened(() => {
      setIsActive(Boolean(toolbarItem.attributes.active));
    });

    modalService.onModalClosed(() => {
      setIsActive(Boolean(toolbarItem.attributes.active));
    });
  }, [modalService]);

  return (
    <ToolbarButtonComponent
      prefix={Icon}
      active={isActive}
      onClick={() => onClick({ isMobile, referenceElement })}
      dataHook={dataHook}
      ariaLabel={tooltip}
      ref={setReferenceElement}
      {...(showLabel ? { label: tooltip } : { tooltip })}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
