import { resolveColorToDisplayHex } from './/resolve-color-to-display-hex.js';
import { usePanelContainerElement } from './../ui-components/index.js';

export const useResolveDisplayColor = () => {
  const containerEl = usePanelContainerElement();
  return (color: string | undefined) => resolveColorToDisplayHex(color, containerEl);
};
